/*
 * dap_lm.c -- LM digital autopilot against the real AGC code (yaAGC oracle).
 *
 * Inputs and expected words: tools/oracle/cases/dap_lm.spec / .txt
 * (Luminary099), generated by tools/oracle/cases/gen/gen_dap_lm.py.
 * 1/ACCS + 1/ACCONT (jet accelerations, coupling coefficients, gimbal
 * jerks, the 48-word TJETLAW parameter block), TJETLAW for P, U and V with
 * positive and negative errors, rate-limited and RUFLAW cases, GPMATRIX
 * (the T4RUPT DAP matrix) and one pass of the KALMAN_FILTER rate/offset
 * estimator (RATELOOP, ROTORQUE, BACKP, offset estimator).
 *
 * Tolerances (LSB of the AGC word): see docs/modules/oracle-cases.md.
 */
#include <stdio.h>

#include <string.h>

#include "../../src/lm/dap/internal.h"
#include "agc/core/assert.h"
#include "agc/core/interp.h"
#include "agc/core/state.h"
#include "agc/exec/exec.h"
#include "agc/guidance/guidance.h"
#include "agc/io/service.h"
#include "agc/lm/dap.h"
#include "oracle_txt.h"

bool agc_assert_report(const char *file, int line, const char *expr)
{
    (void) printf("assert %s:%d %s\n", file, line, expr);

    return (false);
}

#define DAPBOOLS_WORD 13
#define FLGWRD10      10

static void fresh(void)
{
    agc_state_init(AGC_VEHICLE_LM);
    (void) agc_exec_init();
    (void) agc_waitlist_init();
    (void) agc_guid_init(AGC_VEHICLE_LM);
    (void) agc_lm_dap_fresh_start();
    /* The AGC runs start from zeroed erasable: drop the fresh-start pad
     * values (1/ACCSET block, gains) the C keeps in lm_dap_t.            */
    (void) memset(lm_dap_state(), 0, sizeof (lm_dap_t));
}

static void cmp_sp(const char *t, const char *what, long got, const char *n,
                   long tol)
{
    (void) oracle_cmp(t, what, got, oracle_out_sp(t, n), tol);
}

static void accs(const char *t, long tol)
{
    lm_dap_t *d = lm_dap_state();

    fresh();
    agc_guid_state()->lm.mass   = oracle_in_dp(t, "MASS", 0);
    agc_guid_state()->lm.abdelv = (agc_sp_t) oracle_in(t, "ABDELV", 0);
    agc_erase_set_csmmass((agc_sp_t) oracle_in(t, "CSMMASS", 0));
    d->hiascent = (agc_sp_t) oracle_in(t, "HIASCENT", 0);
    d->db       = (agc_sp_t) oracle_in(t, "DB", 0);
    d->aosq     = (agc_sp_t) oracle_in(t, "AOSQ", 0);
    d->aosq_lo  = (agc_sp_t) oracle_in(t, "AOSQ", 1);
    d->aosr     = (agc_sp_t) oracle_in(t, "AOSQ", 2);
    d->aosr_lo  = (agc_sp_t) oracle_in(t, "AOSQ", 3);
    d->ch5mask  = oracle_in_raw(t, "CH5MASK", 0);
    agc_flagword_set(DAPBOOLS_WORD, oracle_in_raw(t, "DAPBOOLS", 0));
    agc_flagword_set(FLGWRD10, oracle_in_raw(t, "FLGWRD10", 0));
    (void) agc_lm_dap_jet_accel_update();
    oracle_require_ok(t, "ENDOFJOB");
    cmp_sp(t, "LEMMASS", agc_erase_lemmass(), "LEMMASS", 0);

    for (int k = 0; k < 5; k++)
    {
        char n[16];

        (void) snprintf(n, sizeof n, "E6,%04o", 01530 + k);
        cmp_sp(t, n, d->jacc[k], n, tol);
    }

    cmp_sp(t, "COEFFQ", d->coeffq, "COEFFQ", tol);
    cmp_sp(t, "COEFFR", d->coeffr, "COEFFR", tol);
    cmp_sp(t, "L,PVT-CG", d->l_pvt_cg, "E6,1527", tol);
    cmp_sp(t, "ACCDOTQ", d->accdotq, "ACCDOTQ", tol);
    cmp_sp(t, "ACCDOTR", d->accdotr, "ACCDOTR", tol);
    cmp_sp(t, "KQ", d->kq, "KQ", tol);
    cmp_sp(t, "KRDAP", d->krdap, "KRDAP", tol);
    cmp_sp(t, "QACCDOT", d->qaccdot, "QACCDOT", tol);
    cmp_sp(t, "RACCDOT", d->raccdot, "RACCDOT", tol);
    cmp_sp(t, "-2JETLIM", d->neg_2jetlim, "-2JETLIM", 0);
    cmp_sp(t, "ALLOWGTS", d->allowgts, "ALLOWGTS", 0);
    (void) oracle_cmp(t, "MASS", agc_guid_state()->lm.mass,
                      oracle_out_dp(t, "MASS"), 0);

    /* AOSQ = AOSR = 0 leaves AOSV = -0 in the AGC; 1/ACCONT models that
     * sign (SIGNAOS = 1), so the V-axis pairs are compared as stored.    */
    for (int k = 0; k < LM_BLOCK_N; k++)
    {
        char n[16];

        (void) snprintf(n, sizeof n, "E6,%04o", 01547 + k);
        cmp_sp(t, n, d->block[k], n, tol);
    }
}

static void tjetlaw(const char *t, long tol)
{
    lm_dap_t *d = lm_dap_state();

    fresh();

    for (int k = 0; k < LM_BLOCK_N; k++)
    {
        d->block[k] = (agc_sp_t) oracle_in(t, "BLOCKTOP", k);
    }

    d->e        = (agc_sp_t) oracle_in(t, "E", 0);
    d->edot     = (agc_sp_t) oracle_in(t, "EDOT", 0);
    d->axisctr  = (agc_sp_t) oracle_in(t, "AXISCTR", 0);
    d->sensetyp = (agc_sp_t) oracle_in(t, "SENSETYP", 0);
    d->tj[0]    = 0;
    d->tj[1]    = 0;
    d->tj[2]    = 0;
    (void) lm_dap_tjetlaw();
    oracle_require_ok(t, "ENDOFJOB");
    cmp_sp(t, "TJP", d->tj[0], "TJP", tol);
    cmp_sp(t, "TJU", d->tj[1], "TJU", tol);
    cmp_sp(t, "TJV", d->tj[2], "TJV", tol);
    cmp_sp(t, "NUMBERT", d->numbert, "NUMBERT", 0);
    cmp_sp(t, "FIREFCT", d->firefct, "FIREFCT", tol);
}

/* GPMATRIX from CDUX, CDUZ (the run's set CDUX=x,y,z words 0 and 2). */
static void gimbal_matrix(const char *t)
{
    agc_erase_set_cdux(oracle_in_raw(t, "CDUX", 0));
    agc_erase_set_cduz(oracle_in_raw(t, "CDUX", 2));
    (void) agc_t4_gimbal_matrix();
}

static void gpm(const char *t)
{
    fresh();
    gimbal_matrix(t);
    oracle_require_ok(t, "RESUME");
    cmp_sp(t, "M11", agc_erase_m11(), "M11", 0);
    cmp_sp(t, "M21", agc_erase_m21(), "M21", 0);
    cmp_sp(t, "M22", agc_erase_m22(), "M22", 0);
    cmp_sp(t, "M31", agc_erase_m31(), "M31", 0);
    cmp_sp(t, "M32", agc_erase_m32(), "M32", 0);
    cmp_sp(t, "COSMG", agc_erase_cosmg(), "COSMG", 0);
}

static void kalman(const char *t, const char *gp, long tol)
{
    lm_dap_t *d = lm_dap_state();

    fresh();
    gimbal_matrix(gp); /* the M11..M32 the generator copied from gp */

    for (int k = 0; k < 3; k++)
    {
        d->tj[k]     = (agc_sp_t) oracle_in(t, "TJP", k);
        d->nojets[k] = (agc_sp_t) oracle_in(t, "NO.PJETS", k);
        d->jacc[k]   = (agc_sp_t) oracle_in(t, "E6,1530", k);
        d->dapcdu[k] = oracle_in_raw(t, "DAPTREG4", k);
    }

    d->oldxforp   = oracle_in_raw(t, "OLDXFORP", 0);
    d->oldyforp   = oracle_in_raw(t, "OLDXFORP", 1);
    d->oldzforq   = oracle_in_raw(t, "OLDXFORP", 2);
    d->trapedp    = (agc_sp_t) oracle_in(t, "TRAPEDP", 0);
    d->trapedq    = (agc_sp_t) oracle_in(t, "TRAPEDP", 1);
    d->trapedr    = (agc_sp_t) oracle_in(t, "TRAPEDP", 2);
    d->nptraps    = (agc_sp_t) oracle_in(t, "TRAPEDP", 3);
    d->nqtraps    = (agc_sp_t) oracle_in(t, "TRAPEDP", 4);
    d->nrtraps    = (agc_sp_t) oracle_in(t, "TRAPEDP", 5);
    d->omegap     = (agc_sp_t) oracle_in(t, "OMEGAP", 0);
    d->omegaq     = (agc_sp_t) oracle_in(t, "OMEGAP", 1);
    d->omegar     = (agc_sp_t) oracle_in(t, "OMEGAP", 2);
    d->aosqterm   = (agc_sp_t) oracle_in(t, "AOSQTERM", 0);
    d->aosrterm   = (agc_sp_t) oracle_in(t, "AOSQTERM", 1);
    d->aosq       = (agc_sp_t) oracle_in(t, "AOSQ", 0);
    d->aosq_lo    = (agc_sp_t) oracle_in(t, "AOSQ", 1);
    d->aosr       = (agc_sp_t) oracle_in(t, "AOSQ", 2);
    d->aosr_lo    = (agc_sp_t) oracle_in(t, "AOSQ", 3);
    d->dxerror    = (agc_sp_t) oracle_in(t, "DXERROR", 0);
    d->dxerror_lo = (agc_sp_t) oracle_in(t, "DXERROR", 1);
    d->qerror     = (agc_sp_t) oracle_in(t, "DXERROR", 2);
    d->dyerror_lo = (agc_sp_t) oracle_in(t, "DXERROR", 3);
    d->rerror     = (agc_sp_t) oracle_in(t, "DXERROR", 4);
    d->dzerror_lo = (agc_sp_t) oracle_in(t, "DXERROR", 5);
    d->plast      = (agc_sp_t) oracle_in(t, "PLAST", 0);
    d->qlast      = (agc_sp_t) oracle_in(t, "PLAST", 1);
    d->rlast      = (agc_sp_t) oracle_in(t, "PLAST", 2);
    d->lmtrap     = (agc_sp_t) oracle_in(t, "LMTRAP", 0);
    d->lmomegan   = (agc_sp_t) oracle_in(t, "LMTRAP", 1);
    d->lmkaosn    = (agc_sp_t) oracle_in(t, "LMTRAP", 2);
    d->qaccdot    = (agc_sp_t) oracle_in(t, "QACCDOT", 0);
    d->raccdot    = (agc_sp_t) oracle_in(t, "RACCDOT", 0);

    for (int k = 0; k < 6; k++)
    {
        d->downtork[k] = 0;
    }

    agc_flagword_set(DAPBOOLS_WORD, oracle_in_raw(t, "DAPBOOLS", 0));
    (void) lm_dap_rateloop();
    (void) lm_dap_backp();
    (void) lm_dap_offset_est();
    oracle_require_ok(t, "PRETIMCK");
    cmp_sp(t, "OMEGAP", d->omegap, "OMEGAP", tol);
    cmp_sp(t, "OMEGAQ", d->omegaq, "OMEGAQ", tol);
    cmp_sp(t, "OMEGAR", d->omegar, "OMEGAR", tol);
    cmp_sp(t, "TRAPEDP", d->trapedp, "TRAPEDP", tol);
    cmp_sp(t, "TRAPEDQ", d->trapedq, "TRAPEDQ", tol);
    cmp_sp(t, "TRAPEDR", d->trapedr, "TRAPEDR", tol);
    cmp_sp(t, "NPTRAPS", d->nptraps, "NPTRAPS", 0);
    cmp_sp(t, "NQTRAPS", d->nqtraps, "NQTRAPS", 0);
    cmp_sp(t, "NRTRAPS", d->nrtraps, "NRTRAPS", 0);
    (void) oracle_cmp(t, "AOSQ", (long) d->aosq * 16384 + d->aosq_lo,
                      oracle_out_dp(t, "AOSQ"), tol);
    (void) oracle_cmp(t, "AOSR", (long) d->aosr * 16384 + d->aosr_lo,
                      oracle_out_dp(t, "AOSR"), tol);
    cmp_sp(t, "ALPHAQ", d->alphaq, "ALPHAQ", tol);
    cmp_sp(t, "ALPHAR", d->alphar, "ALPHAR", tol);
    cmp_sp(t, "AOSQTERM", d->aosqterm, "AOSQTERM", tol);
    cmp_sp(t, "AOSRTERM", d->aosrterm, "AOSRTERM", tol);
    (void) oracle_cmp(t, "DXERROR", (long) d->dxerror * 16384 + d->dxerror_lo,
                      oracle_out_dp(t, "DXERROR"), tol);
    (void) oracle_cmp(t, "DYERROR", (long) d->qerror * 16384 + d->dyerror_lo,
                      oracle_out_dp(t, "DYERROR"), tol);
    (void) oracle_cmp(t, "DZERROR", (long) d->rerror * 16384 + d->dzerror_lo,
                      oracle_out_dp(t, "DZERROR"), tol);
    cmp_sp(t, "JETRATE", d->jetrate[0], "JETRATE", tol);
    cmp_sp(t, "JETRATEQ", d->jetrate[1], "JETRATEQ", tol);
    cmp_sp(t, "JETRATER", d->jetrate[2], "JETRATER", tol);
    cmp_sp(t, "TJP", d->tj[0], "TJP", 0);
    cmp_sp(t, "TJU", d->tj[1], "TJU", 0);
    cmp_sp(t, "TJV", d->tj[2], "TJV", 0);
    (void) oracle_cmp(t, "OLDXFORP", d->oldxforp,
                      (long) oracle_out_raw(t, "OLDXFORP"), 0);
    (void) oracle_cmp(t, "OLDYFORP", d->oldyforp,
                      (long) oracle_out_raw(t, "OLDYFORP"), 0);
    (void) oracle_cmp(t, "OLDZFORQ", d->oldzforq,
                      (long) oracle_out_raw(t, "OLDZFORQ"), 0);

    for (int k = 0; k < 6; k++)
    {
        char n[16];

        (void) snprintf(n, sizeof n, (k == 0) ? "DOWNTORK" : "DOWNTORK+%d", k);
        cmp_sp(t, n, d->downtork[k], n, 0);
    }
}

int main(void)
{
    if (!oracle_load("dap_lm"))
    {
        (void) printf("oracle_dap_lm: SKIP (case files not found)\n");

        return (0);
    }

    accs("accs_dps", 0);
    accs("accs_aps", 0);
    accs("accs_docked", 0);
    accs("accs_dps_wide", 0);
    accs("accs_aos_small", 0);
    accs("accs_aos_some", 0);
    accs("accs_aos_big", 0);
    accs("accs_aos_bigneg", 0);
    accs("accs_aos_netneg", 0);
    accs("accs_aos_vbig", 0);
    accs("accs_aos_ovf", 0);
    accs("accs_aos_fail1", 0);
    accs("accs_aos_fail2", 0);
    accs("accs_aos_drift", 0);
    accs("accs_aos_aps", 0);
    accs("accs_aos_wide", 0);
    tjetlaw("tjet_p_small", 0);
    tjetlaw("tjet_p_neg", 0);
    tjetlaw("tjet_u_mid", 0);
    tjetlaw("tjet_v_rate", 0);
    tjetlaw("tjet_u_large", 1); /* RUFLAW: 1 LSB */
    tjetlaw("tjet_v_coast", 0);
    tjetlaw("tjet_p_aps", 0);
    tjetlaw("tjet_u_aps", 0);
    gpm("gpm_a");
    gpm("gpm_b");
    gpm("gpm_c");
    kalman("kal_coast", "gpm_a", 0);
    kalman("kal_jets", "gpm_a", 0);
    kalman("kal_powered", "gpm_b", 0);
    kalman("kal_bigtrap", "gpm_c", 0);

    return (oracle_finish("oracle_dap_lm"));
}
